using System;
using System.IO;
using System.Text;
using CargoWise.eHub.Products.NZCustoms.Common;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CargoWise.eHub.Products.NZCustoms.Tests
{
	[TestClass]
	public class LodgementDocumentCollectionTests
	{
		[TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
		public void LodgementDocumentCollection_Create_Xml()
		{
			var logger = new TestLogger();

			using (var stream = new MemoryStream(Convert.FromBase64String(@"")))
			{
				var documents = LodgementDocumentCollection.Create(logger, stream);
				Assert.AreEqual(1, documents.Length);
				Assert.AreEqual(1718, documents[0].Content.Length);
				Assert.AreEqual(Constants.LegacyDeclarationMediaType, documents[0].DocumentMediaType);
				Assert.AreEqual(Constants.DeclarationDocumentType, documents[0].DocumentType);
				Assert.AreEqual(Constants.DeclarationContentId, documents[0].FileName);
			}
		}

		[TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
		public void LodgementDocumentCollection_Create_MultipleAttachments()
		{
			var logger = new TestLogger();

			using (var stream = new MemoryStream(Convert.FromBase64String(@"")))
			{
				var documents = LodgementDocumentCollection.Create(logger, stream);
				Assert.AreEqual(3, documents.Length);

				Assert.AreEqual(2399, documents[0].Content.Length);
				Assert.AreEqual(Constants.XmlDeclarationMediaType, documents[0].DocumentMediaType);
				Assert.AreEqual(Constants.DeclarationDocumentType, documents[0].DocumentType);
				Assert.AreEqual("Declaration.xml", documents[0].FileName);

				Assert.AreEqual(5647, documents[1].Content.Length);
				Assert.AreEqual("application/pdf", documents[1].DocumentMediaType);
				Assert.AreEqual("OTH", documents[1].DocumentType);
				Assert.AreEqual("CAU - WI00043051_7501WithoutParts_PrintFromMessage.pdf", documents[1].FileName);

				Assert.AreEqual(5826, documents[2].Content.Length);
				Assert.AreEqual("msword_blabla/xml", documents[2].DocumentMediaType);
				Assert.AreEqual("PAC", documents[2].DocumentType);
				Assert.AreEqual("CAU - WI00043051_7501WithParts_PrintFromEntry.pdf", documents[2].FileName);
			}
		}

        [TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
        [ExpectedException(typeof(NZCustomsInvalidOperationException), "Attachment document file cannot be empty. Please correct and resend the message.")]
        public void LodgementDocumentCollection_Create_MultipleAttachments_EmptyFile()
        {
            var logger = new TestLogger();
            using (var stream = new MemoryStream(Convert.FromBase64String(@"")))
            {
                var documents = LodgementDocumentCollection.Create(logger, stream);
            }
        }

        [TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
		public void LodgementDocumentCollection_Create_MultipleAttachments_DeclarationXmlError()
		{
			var logger = new TestLogger();

			using (var stream = new MemoryStream(Convert.FromBase64String(@"")))
			{
				var documents = LodgementDocumentCollection.Create(logger, stream);
				Assert.AreEqual(3, documents.Length);

				Assert.AreEqual(2401, documents[0].Content.Length);
				Assert.AreEqual(Constants.XmlDeclarationMediaType, documents[0].DocumentMediaType);
				Assert.AreEqual(Constants.DeclarationDocumentType, documents[0].DocumentType);
				Assert.AreEqual("Declaration.xml", documents[0].FileName);

				Assert.AreEqual(5647, documents[1].Content.Length);
				Assert.AreEqual("application/pdf", documents[1].DocumentMediaType);
				Assert.AreEqual("OTH", documents[1].DocumentType);
				Assert.AreEqual("CAU - WI00043051_7501WithoutParts_PrintFromMessage.pdf", documents[1].FileName);

				Assert.AreEqual(5826, documents[2].Content.Length);
				Assert.AreEqual("application/pdf", documents[2].DocumentMediaType);
				Assert.AreEqual("OTH", documents[2].DocumentType);
				Assert.AreEqual("CAU - WI00043051_7501WithParts_PrintFromEntry.pdf", documents[2].FileName);

				Assert.AreEqual("Warn - UpdateDocumentsFromDeclaration error Exception message: The 'AdditionalDocument11' start tag on line 19 position 6 does not match the end tag of 'AdditionalDocument'. Line 22, position 7.", logger.Log.Trim());
			}
		}

		[TestMethod, TestProperty("DAT:CapabilityRequirements", "BIZTALK2020")]
		[ExpectedException(typeof(NZCustomsInvalidOperationException), "Attachment document filename should be unique. Please correct and resend the message.")]
